#!/usr/bin/env node
// Bundle the Actuarial Tools engine (src/lib/tools/) into one dependency-free
// ES module for the serverless functions, which are plain JS and can't import
// the app's TypeScript (docs/actuarial-tools.md §8.2):
//
//   npm run tools:bundle      → api/_tools/engine.js
//                               src/data/conceptTools.json
//
// The bundle is committed, and src/lib/tools/bundle.test.ts rebuilds it and
// fails when the committed copy differs — so the app and the MCP connector
// always run the same engine (R1). Run this after any change under src/lib/tools/.
//
// It also writes src/data/conceptTools.json: which tools name each concept page,
// so a concept page can offer its tool without loading the engine
// (src/lib/conceptTools.ts, held to the registry by conceptTools.test.ts).

import { writeFile } from 'node:fs/promises'
import path from 'node:path'
import { fileURLToPath } from 'node:url'
import { build } from 'esbuild'

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..')
export const ENGINE_ENTRY = path.join(ROOT, 'src/lib/tools/index.ts')
export const ENGINE_BUNDLE = path.join(ROOT, 'api/_tools/engine.js')
export const CONCEPT_TOOLS = path.join(ROOT, 'src/data/conceptTools.json')

const BANNER = `// GENERATED by \`npm run tools:bundle\` from src/lib/tools/ — do not edit.
// The Actuarial Tools engine, bundled for the serverless functions (docs/actuarial-tools.md §8.2).
`

/** The bundle's text, built in memory. */
export async function buildToolsEngine() {
  const out = await build({
    entryPoints: [ENGINE_ENTRY],
    bundle: true,
    format: 'esm',
    platform: 'neutral',
    target: 'es2022',
    write: false,
    legalComments: 'none',
    banner: { js: BANNER },
    logLevel: 'silent',
  })
  return out.outputFiles[0].text
}

/**
 * Tools by lowercased concept page name, read off the engine just built.
 * The same rule as `buildConceptTools` in src/lib/conceptTools.ts.
 */
export async function buildConceptToolsJson(engineText) {
  const engine = await import(`data:text/javascript;base64,${Buffer.from(engineText).toString('base64')}`)
  const found = new Map()
  engine.TOOLS.forEach((t, order) => {
    const toolPath = engine.toolPath(t)
    t.method.concepts.forEach((concept, rank) => {
      const key = concept.trim().toLowerCase()
      if (!key) return
      const list = found.get(key) ?? []
      if (list.some(e => e.tool.path === toolPath)) return
      list.push({ tool: { name: t.name, path: toolPath }, rank, data: t.area === 'data' ? 1 : 0, order })
      found.set(key, list)
    })
  })
  const index = {}
  for (const key of [...found.keys()].sort()) {
    index[key] = found.get(key)
      .sort((a, b) => a.rank - b.rank || a.data - b.data || a.order - b.order)
      .map(e => e.tool)
  }
  return `${JSON.stringify(index, null, 2)}\n`
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const engine = await buildToolsEngine()
  await writeFile(ENGINE_BUNDLE, engine)
  console.log(`Wrote ${path.relative(ROOT, ENGINE_BUNDLE)}`)
  await writeFile(CONCEPT_TOOLS, await buildConceptToolsJson(engine))
  console.log(`Wrote ${path.relative(ROOT, CONCEPT_TOOLS)}`)
}
